/bin/bash -c "python - <<'PY'
from PIL import Image,ImageDraw
im=Image.open('first_frame.png').resize((1024,640),Image.Resampling.NEAREST)
d=ImageDraw.Draw(im)
for x in range(0,256,10):
 X=x*4; d.line((X,0,X,640),fill=(255,0,0) if x%50==0 else (255,120,120),width=1)
 if x%20==0: d.text((X+2,2),str(x),fill=(255,255,0))
for y in range(0,160,10):
 Y=y*4; d.line((0,Y,1024,Y),fill=(255,0,0) if y%50==0 else (255,120,120),width=1)
 if y%20==0: d.text((2,Y+2),str(y),fill=(255,255,0))
im.save('.tmp/grid.png')
PY"
